 async function publish(){if(!db||!session){setMessage('Inicia sessão para participar.');return}if(!publicationConsent){setMessage('Confirma a autorização antes de submeter.');return}if(storyMode&&(body.trim().length<80||storyLesson.trim().length<20)){setMessage('Conta-nos um pouco mais sobre o teu percurso e a aprendizagem que queres partilhar.');return}const content=storyMode?['HISTÓRIA PROPOSTA À VOZ DELAS','Ligação ao desporto: '+storyRole,'Modalidade: '+(storySport.trim()||'Não indicada'),'A minha história:',body.trim(),'O que gostaria que outras mulheres levassem desta história:',storyLesson.trim()].join('\\n\\n'):body.trim();const r=await db.from('posts').insert({title:title.trim(),body:content,topic:postTopic,author_id:session.user.id,status:'pending',...(storyMode?{publication_type:'story'}:{})});setMessage(r.error?r.error.message:storyMode?'Proposta recebida para revisão editorial. A publicação não é automática.':'Contributo enviado para moderação.');if(!r.error){setTitle('');setBody('');setStoryLesson('');setStorySport('');setPublicationConsent(false)}}
 async function moderate(id:string,status:'published'|'hidden'){if(!db||!admin)return;const candidate=pending.find(p=>p.id===id);if(status==='published'&&candidate?.publication_type==='story'){setMessage('História editorial: exige aprovação expressa da protagonista.');return}const reason=(moderationReasons[id]||'').trim();if(status==='hidden'&&reason.length<10){setMessage('Indica um motivo com pelo menos 10 caracteres.');return}const r=await db.from('posts').update({status,...(status==='hidden'?{moderation_reason:reason}:{})}).eq('id',id);setMessage(r.error?r.error.message:status==='published'?'Contributo aprovado; autora notificada.':'Contributo rejeitado; autora notificada.');if(!r.error){setPending(p=>p.filter(x=>x.id!==id));await refresh()}}
 async function approveAmbassador(id:string){if(!db||!admin)return;if(!window.confirm('Confirmaste a identidade, a autorização expressa para esta versão final e o estatuto de embaixadora?'))return;const r=await db.from('posts').update({status:'published',publication_type:'ambassador'}).eq('id',id);setMessage(r.error?'Não foi possível aprovar como embaixadora. Confirma a migração SQL: '+r.error.message:'Publicação de embaixadora aprovada.');if(!r.error){setPending(p=>p.filter(x=>x.id!==id));await refresh()}}
 async function addContent(){if(!db||!admin||!session)return;const r=await db.from('contents').insert({title:newContent,summary:newSummary,kind,topic:'Competição',published:true,author_id:session.user.id});setMessage(r.error?r.error.message:'Conteúdo publicado.');if(!r.error){setNewContent('');setNewSummary('');await refresh()}}
 const recommendedOpportunities=[...opportunities].filter(o=>!o.deadline_at||new Date(o.deadline_at).getTime()>=Date.now()).sort((a,b)=>{const score=(o:Opportunity)=>(interests.includes(o.interest)?3:0)+(o.sport&&sports.includes(o.sport)?2:0);return score(b)-score(a)});
