 const intro=(eyebrow:string,heading:string,desc:string)=><div className="intro"><span className="eyebrow">{eyebrow}</span><h1>{heading}</h1><p>{desc}</p></div>;
 const sourceFromReferrer=()=>{try{const ref=document.referrer;if(!ref)return 'direct';const host=new URL(ref).hostname.toLowerCase();if(host===window.location.hostname)return 'direct';if(host.includes('instagram.com')||host.includes('l.instagram.com'))return 'instagram';if(/google\\.|bing\\.|duckduckgo\\.|search\\.yahoo/.test(host))return 'search';return 'referral'}catch{return 'other'}};
 const track=(type:'page_view'|'click'|'story_view',label:string)=>{if(!db||admin)return;let visitor:string|null=null,secret:string|null=null;try{if(localStorage.getItem('invictas-analytics-consent')!=='yes')return;visitor=localStorage.getItem('invictas-analytics-visitor');secret=localStorage.getItem('invictas-analytics-secret');if(!visitor){visitor=crypto.randomUUID();localStorage.setItem('invictas-analytics-visitor',visitor)}if(!secret){secret=crypto.randomUUID();localStorage.setItem('invictas-analytics-secret',secret)}}catch{return}void db.rpc('track_site_event_verified',{p_type:type,p_label:label,p_visitor:visitor,p_source:sourceFromReferrer(),p_secret:secret}).then(()=>{})};
 useEffect(()=>{try{const choice=localStorage.getItem('invictas-analytics-consent');if(choice==='yes'||choice==='no')setAnalyticsConsent(choice)}catch{}},[]);
 useEffect(()=>{if(!db)return;track('page_view','Início')},[]);
 useEffect(()=>{if(!db||!admin)return;void Promise.all([db.rpc('site_analytics_summary'),db.rpc('site_visitor_summary'),db.rpc('site_traffic_summary')]).then(([events,visitors,traffic])=>{if(events.error||visitors.error||traffic.error)setAnalyticsError('Analytics indisponível. Confirma a migração SQL e as permissões.');else{setAnalyticsRows(events.data||[]);setVisitorStats(visitors.data||[]);setTrafficStats(traffic.data||[])}})},[admin]);
 const setConsent=async(choice:'yes'|'no')=>{if(choice==='no'){let previous:string|null=null,secret:string|null=null;try{previous=localStorage.getItem('invictas-analytics-visitor');secret=localStorage.getItem('invictas-analytics-secret');localStorage.setItem('invictas-analytics-consent','no')}catch{}setAnalyticsConsent('no');if(previous&&db){if(!secret){setMessage('A recolha de estatísticas foi desativada, mas não é possível comprovar a titularidade dos registos antigos. Mantivemos o identificador neste dispositivo para permitir um pedido de eliminação assistido.');return}const verified=await db.rpc('erase_visitor_events_verified',{p_visitor:previous,p_secret:secret});if(verified.error){setMessage('A recolha de estatísticas foi desativada, mas não foi possível confirmar a eliminação do histórico. Mantivemos os identificadores neste dispositivo para poderes repetir o pedido.');return}}else if(previous&&!db){setMessage('A recolha foi desativada, mas a eliminação do histórico exige ligação à base de dados.');return}try{localStorage.removeItem('invictas-analytics-visitor');localStorage.removeItem('invictas-analytics-secret')}catch{}return}try{localStorage.setItem('invictas-analytics-consent','yes');if(!localStorage.getItem('invictas-analytics-visitor'))localStorage.setItem('invictas-analytics-visitor',crypto.randomUUID());if(!localStorage.getItem('invictas-analytics-secret'))localStorage.setItem('invictas-analytics-secret',crypto.randomUUID())}catch{}setAnalyticsConsent('yes')};
