 const storyDetail=selectedStory?<article className="inv-story-detail"><button className="text-link" onClick={()=>setStoryId(null)}>← Voltar às histórias</button><span className="eyebrow">{selectedStory.publication_type==='ambassador'?'EMBAIXADORA INVICTAS':'HISTÓRIA DA COMUNIDADE'} · {selectedStory.topic}</span><h1>{selectedStory.title}</h1><p className="inv-story-detail-date">{new Date(selectedStory.created_at).toLocaleDateString('pt-PT',{day:'numeric',month:'long',year:'numeric'})}</p><div className="inv-story-detail-body">{selectedStory.body.replace(/^HISTÓRIA PROPOSTA À VOZ DELAS\\n\\n/,'').split(/\\n\\n/).map((paragraph,i)=><p key={i}>{paragraph}</p>)}</div><div className="inv-story-detail-actions"><button onClick={()=>{track('click','partilhar_historia');if(typeof navigator!=='undefined'&&navigator.share){void navigator.share({title:selectedStory.title,url:window.location.href}).catch(()=>{})}else if(navigator.clipboard){void navigator.clipboard.writeText(window.location.href).then(()=>setMessage('Ligação copiada.'))}}}>Partilhar esta história ↗</button><button onClick={()=>{setStoryMode(false);go('Entre Nós')}}>Participar na conversa ↗</button></div>{message&&<p role="status">{message}</p>}<footer className="inv-story-editorial-footer"><span className="eyebrow">A VOZ DELAS · IDENTIDADE E AUTORIZAÇÃO</span><p>As histórias convidadas são identificadas e publicadas mediante autorização da protagonista. A assinatura manuscrita é apresentada apenas quando fornecida e autorizada pela própria; nunca é criada ou simulada pela redação.</p><p className="inv-story-detail-note">Esta história passou por moderação editorial. Não representa aconselhamento médico ou profissional.</p></footer></article>:null;
 const storyCards=<div className="story-grid"><article className="story-feature"><span className="eyebrow">A VOZ DELAS · EM PREPARAÇÃO</span><div className="story-art"><span>ELAS<br/>FAZEM<br/>HISTÓRIA<span className="dot">.</span></span></div><h3>Histórias reais, sem filtros nem estereótipos.</h3><p>Queremos ouvir atletas, treinadoras, dirigentes e todas as mulheres que fazem parte do desporto.</p><button className="text-link" onClick={()=>go('A Voz Delas')}>Conhecer as histórias ↗</button></article><div className="story-side"><article className="story-mini"><span className="eyebrow">TEMA EM DESTAQUE</span><span className="mini-num">01 / 03</span><h3>Ser mulher. Ser atleta. Ser muitas coisas.</h3><p>Identidade, exigência e os diferentes papéis de quem vive o desporto.</p></article><article className="story-mini contrast"><span className="eyebrow">QUEREMOS OUVIR-TE</span><span className="mini-num">02 / 03</span><h3>Qual é a tua história?</h3><p>A INVICTAS começa por escutar. As primeiras entrevistas serão publicadas com autorização das participantes.</p><button className="text-link" onClick={()=>go('Entre Nós')}>Participar ↗</button></article></div></div>;
